import os
import re
from typing import List, Dict, Any, Tuple

import requests


class TextContentSafety:
    """
    Uses OpenAI Moderations API to flag unsafe spans in text.
    If unsafe content is detected, it redacts approximate spans based on
    keyword/phrase heuristics guided by moderation categories.
    """

    OPENAI_MODERATION_URL = "https://api.openai.com/v1/moderations"
    DEFAULT_MODEL = "omni-moderation-latest"

    def __init__(self, api_key: str | None = None, model: str | None = None, timeout: float = 30.0):
        self.api_key = api_key or os.getenv("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("OPENAI_API_KEY is required")
        self.model = model or self.DEFAULT_MODEL
        self.timeout = timeout

    def analyze(self, text: str) -> Dict[str, Any]:
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }
        payload = {"model": self.model, "input": text}
        resp = requests.post(self.OPENAI_MODERATION_URL, headers=headers, json=payload, timeout=self.timeout)
        resp.raise_for_status()
        data = resp.json()

        result = data["results"][0]
        categories = result.get("categories", {})
        scores = result.get("category_scores", {})
        flagged = bool(result.get("flagged", False))

        spans = self._find_unsafe_spans(text, categories, scores)

        return {
            "flagged": flagged or bool(spans),
            "categories": categories,
            "scores": scores,
            "unsafe_spans": spans,
            "redacted_text": self._redact_spans(text, spans),
        }

    def _find_unsafe_spans(self, text: str, categories: Dict[str, bool], scores: Dict[str, float]) -> List[Dict[str, Any]]:
        patterns: List[Tuple[str, str]] = [
            ("hate", r"\b(hate|hateful|slur|bigot|bigoted)\b"),
            ("self-harm", r"\b(suicide|kill myself|self[-\s]?harm|cut myself|end my life)\b"),
            ("sexual", r"\b(porn|explicit sex|nude|naked|sexual)\b"),
            ("violence", r"\b(kill|murder|shoot|stab|bomb|attack)\b"),
            ("harassment", r"\b(assault|harass|abuse|threaten|threat)\b"),
        ]

        unsafe_spans: List[Dict[str, Any]] = []

        active_categories = {k for k, v in categories.items() if v}
        for label, pattern in patterns:
            if not self._category_matches(label, active_categories, scores):
                continue
            for m in re.finditer(pattern, text, flags=re.IGNORECASE):
                unsafe_spans.append(
                    {
                        "start": m.start(),
                        "end": m.end(),
                        "text": m.group(0),
                        "label": label,
                    }
                )

        unsafe_spans = self._merge_spans(unsafe_spans)
        return unsafe_spans

    def _category_matches(self, label: str, active_categories: set, scores: Dict[str, float]) -> bool:
        mapping = {
            "hate": ["hate", "hate/threatening"],
            "self-harm": ["self-harm", "self-harm/intent", "self-harm/instructions"],
            "sexual": ["sexual", "sexual/minors"],
            "violence": ["violence", "violence/graphic"],
            "harassment": ["harassment", "harassment/threatening"],
        }
        if any(cat in active_categories for cat in mapping.get(label, [])):
            return True
        # fallback threshold if the API returns scores but not flags
        score_keys = mapping.get(label, [])
        return any(scores.get(cat, 0.0) >= 0.5 for cat in score_keys)

    def _merge_spans(self, spans: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        if not spans:
            return []
        spans = sorted(spans, key=lambda x: (x["start"], x["end"]))
        merged = [spans[0].copy()]
        for s in spans[1:]:
            last = merged[-1]
            if s["start"] <= last["end"]:
                last["end"] = max(last["end"], s["end"])
                last["text"] = last.get("text", "") + text[last["end"]:s["end"]] if False else last.get("text", "")
                if "label" not in last:
                    last["label"] = s.get("label")
                elif s.get("label") != last.get("label"):
                    last["label"] = f"{last['label']},{s.get('label')}"
            else:
                merged.append(s.copy())
        return merged

    def _redact_spans(self, text: str, spans: List[Dict[str, Any]], replacement: str = "[REDACTED]") -> str:
        if not spans:
            return text
        spans = sorted(spans, key=lambda x: x["start"])
        parts = []
        cursor = 0
        for s in spans:
            start, end = max(0, s["start"]), min(len(text), s["end"])
            if start > cursor:
                parts.append(text[cursor:start])
            parts.append(replacement)
            cursor = max(cursor, end)
        if cursor < len(text):
            parts.append(text[cursor:])
        return "".join(parts)


def flag_or_redact(text: str, api_key: str | None = None, redact: bool = True) -> Dict[str, Any]:
    """
    Convenience helper returning moderation analysis and optionally redacted text.
    """
    safety = TextContentSafety(api_key=api_key)
    result = safety.analyze(text)
    if not redact:
        result.pop("redacted_text", None)
    return result
